// Selektovanje elemenata za pop-up reklamu
const popupOverlay = document.querySelector(".popup-overlay");
const skipButton = document.querySelector(".popup-container .skip-button");
const visitButton = document.querySelector(".popup-container .visit-button");

let remainingTime = 5;
let allowedToSkip = false;
let popupTimer;

// Funkcija za kreiranje kolačića
const createPopupCookie = () => {
    const expiresDays = 30;
    const date = new Date();
    date.setTime(date.getTime() + expiresDays * 24 * 60 * 60 * 1000);
    const expires = "expires=" + date.toUTCString();
    document.cookie = "popupCookie=true; " + expires + "; path=/;";
};

// Prikazivanje reklame
const showAd = () => {
    if (popupOverlay) {
        popupOverlay.classList.add("active");
        popupTimer = setInterval(() => {
            skipButton.innerHTML = i18next.t('popup.skip', { time: remainingTime });
            remainingTime--;

            if (remainingTime < 0) {
                allowedToSkip = true;
                skipButton.innerHTML = i18next.t('popup.skipReady');
                clearInterval(popupTimer);
            }
        }, 1000);
    } else {
        console.error("Popup overlay nije pronađen!");
    }
};

// Preskakanje reklame
const skipAd = () => {
    if (popupOverlay) {
        popupOverlay.classList.remove("active");
        createPopupCookie();
    }
};

if (skipButton) {
    skipButton.addEventListener("click", () => {
        if (allowedToSkip) {
            skipAd();
        }
    });
}

// Početak tajmera pri skrolovanju
const startTimer = () => {
    if (window.scrollY > 100) {
        showAd();
        window.removeEventListener("scroll", startTimer);
    }
};

if (!document.cookie.match(/^(.*;)?\s*popupCookie\s*=\s*[^;]+(.*)?$/)) {
    window.addEventListener("scroll", startTimer);
}

// Funkcija za ažuriranje sadržaja u toast notifikaciji
const updateToastContent = () => {
    const toastContainer = document.querySelector(".toast-container");
    const messageTag = toastContainer.querySelector('h3'); // message u toast notifikaciji
    const pTag = toastContainer.querySelector('p'); // content u toast notifikaciji

    // Ako postoji h3 tag unutar toast kontejnera, ažuriraj ga
    if (messageTag) {
        messageTag.innerHTML = i18next.t('toast.message'); // Prevedi sadržaj za message
    }

    // Ako postoji p tag unutar toast kontejnera, ažuriraj ga
    if (pTag) {
        pTag.innerHTML = i18next.t('toast.content'); // Prevedi sadržaj za content
    }

    // Takođe ažuriraj sve ostale elemente, kao što su linkovi i autor
    const authorName = document.querySelector('.author-name');
    if (authorName) {
        authorName.innerHTML = i18next.t('toast.author');
    }
};

// Funkcija za ažuriranje hero sekcije
const updateHeroSection = () => {
    const heroTitle = document.querySelector('.hero h1');
    if (heroTitle) {
        heroTitle.innerHTML = i18next.t('hero.title'); // Prevedi sadržaj za hero sekciju
    }
};

// Podešavanje za toast notifikaciju
document.addEventListener("DOMContentLoaded", () => {
    const toastContainer = document.querySelector(".toast-container");
    const closeBtn = document.querySelector(".toast-container .close");
    const toastLink = document.querySelector(".toast-container a");

    if (!localStorage.getItem("displayToast")) {
        setTimeout(() => {
            if (toastContainer) {
                toastContainer.classList.add("active");
            } else {
                console.error("Element sa klasom 'toast-container' nije pronađen!");
            }
        }, 1000);
    }

    // Funkcija za zatvaranje toasta
    const stopDisplayingToast = () => {
        localStorage.setItem("displayToast", "true");
        if (toastContainer) {
            toastContainer.classList.add("exit");

            setTimeout(() => {
                toastContainer.classList.remove("active", "exit");
            }, 500);
        }
    };

    if (closeBtn) closeBtn.addEventListener("click", stopDisplayingToast);
    if (toastLink) toastLink.addEventListener("click", stopDisplayingToast);
});

const updateVisitButton = () => {
    const visitButton = document.querySelector(".visit-button");
    if (visitButton) {
        visitButton.innerHTML = i18next.t("visitButton");
    } else {
        console.warn("Element sa klasom .visit-button nije pronađen!");
    }
};


